    private ErroCheckout erroDe(PedidoRequest requisicao) {
        return assertThatThrownBy(() -> calculadora.calcular(requisicao))
                .isInstanceOf(PedidoRecusadoException.class)
                .extracting(excecao -> ((PedidoRecusadoException) excecao).erro())
                .asInstanceOf(org.assertj.core.api.InstanceOfAssertFactories.type(ErroCheckout.class))
                .actual();
    }

